/**
 * Style Dictionary build — the single source of truth pipeline.
 *
 * Reads DTCG tokens from tokens/ and emits:
 *   - dist/tokens.css   CSS custom properties (with references preserved)
 *   - dist/tokens.scss  SCSS variables
 *   - dist/tokens.js    Nested ESM object
 *   - tailwind.preset.js  Tailwind preset derived from the same tokens
 *
 * Run with: npm run tokens
 */
import StyleDictionary from 'style-dictionary';

/** Build a nested object from token paths: ['color','purple','600'] -> {color:{purple:{600:value}}} */
function setNested(root, path, value) {
  let node = root;
  path.forEach((seg, i) => {
    if (i === path.length - 1) node[seg] = value;
    else node = node[seg] ??= {};
  });
  return root;
}

const valueOf = (t) => t.$value ?? t.value;
const typeOf = (t) => t.$type ?? t.type;

StyleDictionary.registerFormat({
  name: 'javascript/esm-nested',
  format: ({ dictionary }) => {
    const tree = {};
    for (const t of dictionary.allTokens) setNested(tree, t.path, valueOf(t));
    return `// Generated by Style Dictionary. Do not edit by hand.\nexport default ${JSON.stringify(tree, null, 2)};\n`;
  },
});

StyleDictionary.registerFormat({
  name: 'javascript/tailwind-preset',
  format: ({ dictionary }) => {
    const colors = {};
    const spacing = {};
    const borderRadius = {};
    const fontSize = {};
    const fontFamily = {};
    const fontWeight = {};
    const size = {};

    for (const t of dictionary.allTokens) {
      const v = valueOf(t);
      const [head, second, third] = t.path;
      if (typeOf(t) === 'color') {
        // strip the redundant `color` head so palette classes read
        // text-purple-600 (shadowing Tailwind's stock palette), not
        // text-color-purple-600; semantic groups (text.*, bg.*, button.*, …)
        // keep their head
        setNested(colors, head === 'color' ? t.path.slice(1) : t.path, v);
      } else if (head === 'space') {
        spacing[second] = v;
      } else if (head === 'radius') {
        borderRadius[second] = v;
      } else if (head === 'size') {
        // size.icon.md -> "icon-md"; drives w-*/h-*/size-* utilities
        size[`${second}-${third}`] = v;
      } else if (head === 'font' && second === 'size') {
        fontSize[third] = v;
      } else if (head === 'font' && second === 'family') {
        fontFamily[third] = v.split(',').map((s) => s.trim());
      } else if (head === 'font' && second === 'weight') {
        fontWeight[third] = v;
      }
    }

    // Expose the icon/avatar scale on width, height and the size utility so
    // `w-icon-md`, `h-avatar-lg`, and `size-icon-sm` all resolve.
    const preset = {
      theme: {
        extend: { colors, spacing, borderRadius, fontSize, fontFamily, fontWeight, width: size, height: size, size },
      },
    };
    return (
      `// Generated by Style Dictionary from tokens/. Do not edit by hand.\n` +
      `// Usage (this package is ESM):\n` +
      `//   import rsPreset from '@tripletree/rs-design-system/tailwind';\n` +
      `//   export default { presets: [rsPreset], ... };\n` +
      `export default ${JSON.stringify(preset, null, 2)};\n`
    );
  },
});

const sd = new StyleDictionary({
  source: ['tokens/**/*.json'],
  usesDtcg: true,
  platforms: {
    css: {
      transformGroup: 'css',
      buildPath: 'dist/',
      files: [
        {
          destination: 'tokens.css',
          format: 'css/variables',
          options: { outputReferences: true },
        },
      ],
    },
    scss: {
      transformGroup: 'scss',
      buildPath: 'dist/',
      files: [{ destination: 'tokens.scss', format: 'scss/variables' }],
    },
    js: {
      transformGroup: 'js',
      buildPath: 'dist/',
      files: [{ destination: 'tokens.js', format: 'javascript/esm-nested' }],
    },
    tailwind: {
      transformGroup: 'js',
      buildPath: './',
      files: [{ destination: 'tailwind.preset.js', format: 'javascript/tailwind-preset' }],
    },
  },
});

await sd.cleanAllPlatforms();
await sd.buildAllPlatforms();
console.log('✓ Tokens built → dist/tokens.{css,scss,js} + tailwind.preset.js');
